var stylevar = document.createElement("style");
stylevar.innerText = `
#mainmenu { 
	width: 600px; 
	height: 450px; 
	padding: 0px 3px 0px 3px;
	z-index: 300;
}
.infoblock {
	display: none;
	color: #fff;
	background-color: #000;
	position: fixed;
	margin: 0;
	z-index: 228;
}
#ykvjiaseliieori_overlay {
	display: block;
	pointer-events: none;
	cursor: none;
	width: 100%;
	z-index: 222;
	position: absolute;
	inset: 0;
	margin: auto;
}
.ui-draggable {
	display: none;
	background-color: #0000a8;
	font-family: msdos;
	font-size: 21px; 
	text-align: left;
	box-shadow: 21px 21px 0px #000;
	text-shadow: none;
}
#menufieldset {
    border-style: double;
    border-width: 7px;
    border-color: #57ffff;
    margin-inline-start: 0px;
    margin-inline-end: 0px;
    height: calc(450px - 30px);
    padding: 0px 0px;
}
#menulegend {
    color: #0000a8;
    background-color: #57ffff;
    padding: 0px 10px;
    margin:0 auto;
	width: auto;
}
.menubox {
    width: calc(100% - 10px);
    height: 42px;
    line-height: 42px;
    padding: 0px 0px 0px 10px;
    color: #57ffff;
}
.menubox.current{
	background-color: #57ffff;
    color: #0000a8;
}
.menulabel {
    width: 100%;
    height: 42px;
    line-height: 42px;
    text-align: center;
	color: #ffff57;
}
.menuview {
    display:none;
	padding: 0px;
}
.menuview.current {
    display: block;
    height: calc(100% - 42px);
}
.menutab {
	width: calc(100% - 10px);
    height: 42px;
    line-height: 42px;
    padding: 0px 0px 0px 10px;
    color: #57ffff;
}
#leftinfoline {
	height: 32px;
    line-height: 54px;
    padding: 0px 0px 0px 10px;
    color: #57ffff;
}
#rightinfoline {
    height: 32px;
    line-height: 54px;
    padding: 0px 0px 0px 0px;
    color: #57ffff;
    text-align: right;
}`
document.head.appendChild(stylevar);

let emenu = document.createElement('div');
emenu.id = 'mainmenu';
document.body.appendChild(emenu);

window.addEventListener("keydown", (e) => {
	switch(e.code) {
		case 'ShiftRight':
			if (e.location === KeyboardEvent.DOM_KEY_LOCATION_RIGHT) { //double check xD
			  if (emenu.style.display === 'none'){
				document.exitPointerLock();
				emenu.style.display = 'block';
			  } else {
				emenu.style.display = 'none';
			  }
			}
			break;
		case setcfg.keys.aimlock:
			pushedfuncs.aimlock = true;
			break;
		default: return;
	}
});

window.addEventListener("keyup", (e) => {
	switch(e.code) {
		case setcfg.keys.aimlock:
			pushedfuncs.aimlock = false;
			break;
		default: return;
	}
});

